import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { mkdtemp, mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import test from 'node:test';
// Execute the CLI entry point with isolated module instances. No production
// exports or injectable clients are needed to observe the command's behavior.
let invocation = 0;
async function main(command) {
  const savedArgv = process.argv;
  process.argv = [process.execPath, new URL('./release.mjs', import.meta.url).pathname, command];
  try {
    await import(`./release.mjs?invocation=${++invocation}`);
  } finally {
    process.argv = savedArgv;
  }
}

const repository = 'cysp/terraform-provider-contentful';
const tag = 'v0.0.71';
const releaseNotes = '## [0.0.71]\n\n### Bug fixes\n\n* Preserve published state';
const prefix = 'terraform-provider-contentful_0.0.71_';
const checksum = `${prefix}SHA256SUMS`;
const hash = data => createHash('sha256').update(data).digest('hex');

async function fixture(t) {
  const cwd = process.cwd();
  const directory = await mkdtemp(join(tmpdir(), 'provider-release-test-'));
  const savedEnv = { ...process.env };
  t.after(async () => {
    process.chdir(cwd);
    for (const key of Object.keys(process.env)) if (!(key in savedEnv)) delete process.env[key];
    Object.assign(process.env, savedEnv);
    await rm(directory, { recursive: true, force: true });
  });
  process.chdir(directory);
  await writeFile('.release-please-manifest.json', '{".":"0.0.71"}\n');
  const git = (...args) => execFileSync('git', args, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }).trim();
  git('init', '--quiet');
  git('add', '.release-please-manifest.json');
  git('-c', 'user.name=Release Test', '-c', 'user.email=release@example.invalid', '-c', 'commit.gpgsign=false', '-c', 'core.hooksPath=/dev/null', 'commit', '--quiet', '-m', 'chore(main): release 0.0.71');
  const sha = git('rev-parse', 'HEAD');
  Object.assign(process.env, {
    GITHUB_REPOSITORY: repository,
    GITHUB_REF: `refs/tags/${tag}`,
    GITHUB_REF_NAME: tag,
    GITHUB_SHA: sha,
    GITHUB_TOKEN: 'fixture-token',
    GITHUB_API_URL: 'https://github.invalid',
    GITHUB_OUTPUT: join(directory, 'output'),
    GITHUB_STEP_SUMMARY: join(directory, 'summary'),
    RUNNER_TEMP: directory,
  });
  delete process.env.RELEASE_ID;
  // Exercise bounded waits without sleeping or adding test-only production flags.
  let now = 0;
  t.mock.method(Date, 'now', () => now);
  t.mock.method(globalThis, 'setTimeout', callback => {
    now += 100_000;
    queueMicrotask(callback);
  });
  t.mock.method(console, 'log', () => {});

  await mkdir('dist');
  const artifacts = {
    [`${prefix}linux_amd64.zip`]: Buffer.from('linux archive fixture'),
    [`${prefix}darwin_arm64.zip`]: Buffer.from('darwin archive fixture'),
    [`${prefix}manifest.json`]: Buffer.from('{"version":1,"metadata":{"protocol_versions":["6.0"]}}'),
  };
  artifacts[checksum] = Buffer.from(Object.entries(artifacts).map(([name, bytes]) => `${hash(bytes)}  ${name}\n`).join(''));
  artifacts[`${checksum}.sig`] = Buffer.from('signature fixture; GPG verification runs in the workflow');
  for (const [name, bytes] of Object.entries(artifacts)) await writeFile(join('dist', name), bytes);

  const pr = {
    number: 901, merged: true, merged_at: '2026-10-24T00:00:00Z', merge_commit_sha: sha,
    base: { ref: 'main', repo: { full_name: repository } },
    head: { ref: 'release-please--branches--main', repo: { full_name: repository } },
    body: `Release Please\n---\n\n${releaseNotes}\n\n---\nGenerated by Release Please`,
  };
  const release = {
    id: 71, tag_name: tag, name: tag, draft: true, prerelease: false, immutable: false,
    body: releaseNotes, html_url: `https://github.com/${repository}/releases/tag/${tag}`,
  };
  const data = {
    sha, release, releases: [release], prs: { [sha]: [pr] }, pulls: { 901: pr },
    refs: { [tag]: { object: { type: 'commit', sha } } },
    comparisons: { [`${sha}...main`]: { status: 'ahead' } },
    runs: {}, jobs: {},
    statuses: [{ context: 'codecov/project', state: 'success', creator: { login: 'codecov[bot]' } }],
    analyses: [
      { id: 101, commit_sha: sha, ref: 'refs/heads/main', tool: { name: 'CodeQL' }, category: '/language:go', error: '', created_at: '2026-10-24T00:10:00Z' },
      { id: 102, commit_sha: sha, ref: 'refs/heads/main', tool: { name: 'CodeQL' }, category: '/language:actions', error: '', created_at: '2026-10-24T00:10:00Z' },
    ],
    alerts: {},
    sarif: { runs: [{ tool: { driver: { rules: [] } }, results: [] }] },
    assets: Object.entries(artifacts).map(([name, bytes], index) => ({ id: index + 1, name, state: 'uploaded', size: bytes.length, digest: `sha256:${hash(bytes)}` })),
    calls: [], override: () => undefined,
  };
  // Independent fixtures describe the required workflows; do not import the
  // production list to derive the expected test evidence.
  for (const [index, workflow] of ['test.yml', 'golangci.yml', 'gogenerate.yml', 'govulncheck.yml', 'release-checks.yml'].entries()) {
    const id = 10 + index;
    data.runs[workflow] = [{ id, run_attempt: 1, path: `.github/workflows/${workflow}`, head_sha: sha, head_branch: 'main', event: 'push', status: 'completed', conclusion: 'success' }];
    data.jobs[id] = [{ name: workflow, conclusion: 'success', steps: [] }];
  }
  data.jobs[10] = [
    { name: 'build', conclusion: 'success', steps: [] },
    { name: 'testaccmocked (1.15.*)', conclusion: 'success', steps: [] },
    { name: 'testaccmocked (1.16.*)', conclusion: 'success', steps: [] },
    { name: 'testacc (1.16.*)', conclusion: 'success', steps: [{ name: 'Live acceptance tests', conclusion: 'success' }] },
  ];
  t.mock.method(globalThis, 'fetch', async (input, options = {}) => {
    const url = new URL(input);
    const method = options.method || 'GET';
    const path = url.pathname.replace(`/repos/${repository}/`, '');
    const call = { path, method, url, options };
    data.calls.push(call);
    const override = data.override(call);
    if (override !== undefined) return override;
    assert.equal(url.origin, 'https://github.invalid', 'No test may access a real service');
    assert.equal(options.headers.Authorization, 'Bearer fixture-token');
    const page = Number(url.searchParams.get('page') || '1');
    const json = (value, status = 200) => new Response(JSON.stringify(value), { status });
    if (path.startsWith('git/ref/tags/')) return json(data.refs[path.slice('git/ref/tags/'.length)]);
    if (path.startsWith('compare/')) return json(data.comparisons[path.slice('compare/'.length)]);
    if (path === 'releases') return json(data.releases.slice((page - 1) * 100, page * 100));
    if (/^commits\/.+\/pulls$/.test(path)) return json(data.prs[path.split('/')[1]] || []);
    if (/^pulls\/\d+$/.test(path)) return json(data.pulls[path.split('/')[1]]);
    if (/^actions\/workflows\/.+\/runs$/.test(path)) {
      assert.equal(url.searchParams.get('head_sha'), sha);
      assert.equal(url.searchParams.get('event'), 'push');
      assert.equal(url.searchParams.get('branch'), 'main');
      return json({ workflow_runs: data.runs[path.split('/')[2]] });
    }
    if (/^actions\/runs\/\d+\/attempts\/\d+\/jobs$/.test(path)) return json({ jobs: data.jobs[path.split('/')[2]] });
    if (path === `commits/${sha}/statuses`) return json(data.statuses);
    if (path === 'code-scanning/analyses') {
      assert.equal(url.searchParams.get('ref'), 'refs/heads/main');
      return json(data.analyses.slice((page - 1) * 100, page * 100));
    }
    if (/^code-scanning\/alerts\/\d+$/.test(path)) return json(data.alerts[path.split('/')[2]]);
    if (/^code-scanning\/analyses\/\d+$/.test(path)) {
      assert.equal(options.headers.Accept, 'application/sarif+json');
      return json(data.sarif);
    }
    if (path === 'releases/71/assets') return json(data.assets);
    if (path === 'releases/71') {
      if (method === 'PATCH') {
        assert.deepEqual(JSON.parse(options.body), { draft: false, make_latest: 'true' });
        data.release.draft = false;
        data.release.immutable = true;
      }
      return json(data.release);
    }
    assert.fail(`Unexpected request: ${method} ${path}`);
  });
  data.mutations = () => data.calls.filter(call => call.method !== 'GET');
  data.prepare = async () => {
    await main('prepare');
    assert.equal(await readFile(process.env.GITHUB_OUTPUT, 'utf8'), 'id=71\npublished=false\n');
    process.env.RELEASE_ID = '71';
  };
  return data;
}

test('approved rebase commit is verified and published once; later rerun is read-only', async t => {
  const f = await fixture(t);
  await f.prepare();
  assert.equal(f.mutations().length, 0);
  await main('verify');
  assert.equal(f.mutations().length, 0);
  await main('publish');
  assert.equal(f.mutations().length, 1);
  assert.equal(f.release.immutable, true);
  const before = f.calls.length;
  await main('prepare');
  assert.equal(f.mutations().length, 1);
  assert.ok(f.calls.slice(before).every(call => !call.path.startsWith('actions/') && !call.path.includes('/assets')));
  assert.match(await readFile(process.env.GITHUB_OUTPUT, 'utf8'), /published=true\n$/);
});

test('recovers an existing draft when Release Please outputs were lost, including tag-before-draft ordering', async t => {
  const f = await fixture(t);
  let reads = 0;
  f.override = call => call.path === 'releases' && reads++ === 0 ? new Response('[]') : undefined;
  await f.prepare();
  assert.ok(reads >= 2);
  assert.equal(f.mutations().length, 0);
});

test('approved CRLF PR notes match Release Please normalized release notes', async t => {
  const f = await fixture(t);
  f.pulls[901].body = f.pulls[901].body.replaceAll('\n', '\r\n');
  await f.prepare();
  assert.equal(f.mutations().length, 0);
});

test('lost publication response is reconciled without another mutation', async t => {
  const f = await fixture(t);
  await f.prepare();
  f.override = call => {
    if (call.method !== 'PATCH') return undefined;
    f.release.draft = false;
    f.release.immutable = true;
    throw new Error('connection reset after server committed publication');
  };
  await main('publish');
  assert.equal(f.mutations().length, 1);
});

test('failed publication leaves the draft recoverable', async t => {
  const f = await fixture(t);
  await f.prepare();
  f.override = call => call.method === 'PATCH' ? new Response('{}', { status: 503 }) : undefined;
  await assert.rejects(main('publish'), /HTTP 503/);
  assert.equal(f.release.draft, true);
  assert.equal(f.mutations().length, 1);
});

for (const [name, change, error] of [
  ['tag points elsewhere', f => { f.refs[tag].object.sha = 'b'.repeat(40); }, /Remote tag/],
  ['PR head differs from final rebase commit', f => { f.pulls[901].merge_commit_sha = 'c'.repeat(40); }, /final commit/],
  ['release PR came from a fork', f => { f.pulls[901].head.repo.full_name = 'other/fork'; }, /final commit/],
  ['wrong manifest version', async () => writeFile('.release-please-manifest.json', '{".":"0.0.72"}'), /manifest/],
  ['edited draft notes', f => { f.release.body = 'unreviewed notes'; }, /notes must match/],
  ['prerelease', f => { f.release.prerelease = true; }, /Prereleases/],
  ['release commit left main', f => { f.comparisons[`${f.sha}...main`].status = 'diverged'; }, /belong to main/],
  ['green job skipped live tests', f => { f.jobs[10].at(-1).steps[0].conclusion = 'skipped'; }, /must execute live/],
  ['missing live job', f => { f.jobs[10].pop(); }, /Live acceptance job is missing/],
  ['skipped mock matrix job', f => { f.jobs[10][1].conclusion = 'skipped'; }, /did not succeed/],
  ['failed generation', f => { f.runs['gogenerate.yml'][0].conclusion = 'failure'; }, /gogenerate.yml failed/],
  ['spoofed coverage', f => { f.statuses[0].creator.login = 'other-bot'; }, /must come from Codecov/],
  ['failed coverage', f => { f.statuses[0].state = 'failure'; }, /Coverage failed/],
  ['CodeQL processing error', f => { f.analyses[0].error = 'failed extraction'; }, /failed extraction/],
]) {
  test(`refuses ${name} before any mutation`, async t => {
    const f = await fixture(t);
    await change(f);
    await assert.rejects(main('prepare'), error);
    assert.equal(f.mutations().length, 0);
  });
}

test('PR or other-commit checks cannot stand in for main-push evidence', async t => {
  const f = await fixture(t);
  const run = f.runs['test.yml'][0];
  f.runs['test.yml'] = [{ ...run, event: 'pull_request' }, { ...run, id: 999, head_sha: 'd'.repeat(40) }];
  await assert.rejects(main('prepare'), /Waiting for test.yml/);
  assert.equal(f.mutations().length, 0);
});

test('a newer failed attempt is not masked by an older green run', async t => {
  const f = await fixture(t);
  f.runs['test.yml'].push({ ...f.runs['test.yml'][0], id: 999, conclusion: 'failure' });
  await assert.rejects(main('prepare'), /test.yml failed/);
});

test('main advancing does not substitute its newer CodeQL analysis', async t => {
  const f = await fixture(t);
  f.analyses = f.analyses.map(analysis => ({ ...analysis, commit_sha: 'e'.repeat(40) }));
  await assert.rejects(main('prepare'), /Waiting for CodeQL/);
  assert.equal(f.mutations().length, 0);
});

// GitHub enriches SARIF with alert numbers. Rule metadata can live in query
// pack extensions; use the linked alert for thresholds and dismissal state.
for (const [level, severity, state, blocked] of [
  ['error', null, 'open', true],
  ['warning', 'high', 'open', true],
  ['warning', 'critical', 'dismissed', false],
  ['warning', 'high', 'fixed', true],
  ['warning', 'medium', 'open', false],
]) {
  test(`CodeQL ${level}/${severity}, ${state}`, async t => {
    const f = await fixture(t);
    f.sarif.runs[0] = {
      tool: {
        driver: { name: 'CodeQL', semanticVersion: '2.25.0' },
        extensions: [{ name: 'codeql/go-queries', rules: [{ id: 'go/example' }] }],
      },
      results: [{ ruleId: 'go/example', properties: { 'github/alertNumber': 21 } }],
    };
    f.alerts[21] = { number: 21, state, tool: { name: 'CodeQL' }, rule: { id: 'go/example', severity: level, security_severity_level: severity } };
    if (blocked) await assert.rejects(main('prepare'), /Blocking CodeQL/);
    else await f.prepare();
    assert.equal(f.mutations().length, 0);
  });
}

test('CodeQL findings without GitHub alert identity cannot pass', async t => {
  const f = await fixture(t);
  f.sarif.runs[0].results = [{ ruleId: 'go/example' }];
  await assert.rejects(main('prepare'), /no alert number/);
  assert.equal(f.mutations().length, 0);
});

test('CodeQL alert linkage must match the exact-analysis finding', async t => {
  const f = await fixture(t);
  f.sarif.runs[0].results = [{ ruleId: 'go/example', properties: { 'github/alertNumber': 21 } }];
  f.alerts[21] = { number: 21, state: 'dismissed', tool: { name: 'CodeQL' }, rule: { id: 'go/other' } };
  await assert.rejects(main('prepare'), /rule differs/);
  assert.equal(f.mutations().length, 0);
});

for (const [name, change] of [
  ['wrong uploaded digest', f => { f.assets[0].digest = `sha256:${'0'.repeat(64)}`; }],
  ['partial upload', f => { f.assets[0].state = 'starter'; }],
  ['missing upload', f => { f.assets.pop(); }],
  ['unexpected extra upload', f => { f.assets.push({ ...f.assets[0], name: 'extra.zip' }); }],
  ['duplicate remote name', f => { f.assets[0].name = f.assets[1].name; }],
  ['changed local archive', async () => writeFile(join('dist', `${prefix}linux_amd64.zip`), 'tampered')],
  ['manifest omitted from checksums', async () => {
    const lines = (await readFile(join('dist', checksum), 'utf8')).split('\n').filter(line => !line.includes('_manifest.json'));
    await writeFile(join('dist', checksum), lines.join('\n'));
  }],
]) {
  test(`never publishes ${name}`, async t => {
    const f = await fixture(t);
    await f.prepare();
    await change(f);
    await assert.rejects(main('publish'));
    assert.equal(f.mutations().length, 0);
  });
}

test('notes or release identity changing after preparation prevents publication', async t => {
  const f = await fixture(t);
  await f.prepare();
  f.release.id = 72;
  await assert.rejects(main('publish'), /Release ID changed/);
  assert.equal(f.mutations().length, 0);
});

test('publication rechecks CI after artifacts were built', async t => {
  const f = await fixture(t);
  await f.prepare();
  f.runs['govulncheck.yml'][0].conclusion = 'failure';
  await assert.rejects(main('publish'), /govulncheck.yml failed/);
  assert.equal(f.mutations().length, 0);
});

test('a published mutable release is reported as unsafe without replacing anything', async t => {
  const f = await fixture(t);
  f.release.draft = false;
  await assert.rejects(main('prepare'), /not immutable/);
  assert.equal(f.mutations().length, 0);
});

for (const [ordering, blocked] of [['ahead', true], ['behind', false]]) {
  test(`${blocked ? 'blocks behind an earlier' : 'does not deadlock on a later'} approved draft`, async t => {
    const f = await fixture(t);
    const otherTag = blocked ? 'v0.0.70' : 'v0.0.72';
    const otherSha = 'f'.repeat(40);
    f.releases.push({ ...f.release, id: 72, tag_name: otherTag, name: otherTag });
    f.refs[otherTag] = { object: { type: 'commit', sha: otherSha } };
    const pr = { ...f.pulls[901], number: 902, merge_commit_sha: otherSha };
    f.prs[otherSha] = [pr];
    f.pulls[902] = pr;
    f.comparisons[`${otherSha}...${f.sha}`] = { status: ordering };
    if (blocked) await assert.rejects(main('prepare'), /Resolve earlier approved draft/);
    else await f.prepare();
  });
}

test('finds the candidate after the first page of releases', async t => {
  const f = await fixture(t);
  f.releases.unshift(...Array.from({ length: 100 }, (_, index) => ({ id: index + 1000, tag_name: `old-${index}`, name: `old-${index}`, draft: false })));
  await f.prepare();
  assert.ok(f.calls.some(call => call.path === 'releases' && call.url.searchParams.get('page') === '2'));
});

test('Registry confirmation is separate and never receives a GitHub token', async t => {
  const f = await fixture(t);
  f.override = call => {
    assert.equal(call.url.origin, 'https://registry.terraform.io');
    assert.equal(call.options.headers, undefined);
    return new Response('{"versions":[{"version":"0.0.71"}]}');
  };
  await main('registry');
  assert.match(await readFile(process.env.GITHUB_STEP_SUMMARY, 'utf8'), /0.0.71 is available/);
  assert.equal(f.mutations().length, 0);
});

test('Registry delay reports unconfirmed indexing without undoing publication', async t => {
  const f = await fixture(t);
  f.override = () => new Response('{"versions":[]}');
  await assert.rejects(main('registry'), /has not indexed/);
  assert.match(await readFile(process.env.GITHUB_STEP_SUMMARY, 'utf8'), /GitHub publication is a separate outcome/);
  assert.equal(f.mutations().length, 0);
});
